#pragma once
#include "ksEditSceneTask.h"
#include "ksEditAddressTask.h"
#include "ksEditDecisionTask.h"
#include "ksStateBankDisplayTask.h"
#include "ksStateStoreService.h"
#include <array>
#include <optional>
#include <variant>
#include <stdexcept>
namespace ks {
// Scene selection and patch data policy. The two outgoing requests are native
// children supplied by the owning graph, never execution-address continuations.
class StateSceneCoordinator final {
public:
 enum class Kind {Activate,Apply,Restore,Backup,Copy,Map,Load,Bank,Notify,Knob,SelectBank};
 enum class Component {Scene,Address,Decision,Notify};
 enum class Request {None,VoiceRefresh,UiRefresh};
 struct Input {uint16_t event=0;uint8_t selectedBank=0;bool savePrevious=false;};
 struct RequestInput {uint16_t character=0,event=0;};
 struct Effect {bool read=false,write=false;};
 // Completed domain-call outcomes form a small semantic tree. No machine
 // register bank or per-instruction ABI state is retained while the job runs.
 struct Facts {
  uint32_t table=0,patch=0;uint8_t selected=0,previous=0,bank=0,lastParameter=0,lastEnabled=0,lastOld=0,lastByte=0,oldKnob=0,knobMagnitude=0,lock=0,knobMode=0,mode=0,oldBank=0,selection=0;bool selectedObserved=false,previousObserved=false,loaded=false,applied=false,voice=false,ui=false,parameterUsed=false;
 };
 struct Outcome {Kind kind=Kind::Bank;Input input{};Facts facts{};std::array<unsigned,4>children{{NoNode,NoNode,NoNode,NoNode}};unsigned childCount=0;EditAddressTask address{EditAddressTask::Kind::Bank};static constexpr unsigned NoNode=~0u;};
 static constexpr unsigned NoNode=~0u;
 struct Summary {std::array<Outcome,12>calls{};unsigned count=0;uint16_t presentation=0;bool voiceObserved=false,uiObserved=false;};
 explicit StateSceneCoordinator(Kind k):StateSceneCoordinator(k,Input{}){}
 StateSceneCoordinator(Kind k,Input in):kind_(k),input_(in){summary_.presentation=in.event;push(k,in);}
 Kind kind()const{return kind_;}Component component()const{return component_;}bool complete()const{return !depth_&&request_==Request::None;}unsigned depth()const{return depth_;}uint32_t components()const{return components_;}Request request()const{return request_;}RequestInput requestInput()const{return {summary_.presentation,summary_.presentation};}const Effect&effect()const{return effect_;}const Summary&summary()const{return summary_;}
 template<class T>const T*task()const{return depth_?std::get_if<T>(&frames_[depth_-1]->task):nullptr;}
 bool resumeVoice(uint16_t presentation){if(request_!=Request::VoiceRefresh)return false;summary_.presentation=presentation;summary_.voiceObserved=true;request_=Request::None;auto&t=std::get<StateBankDisplayTask>(frames_[depth_-1]->task);if(!t.retireTail())throw std::logic_error("Invalid scene voice completion");finish();return true;}
 bool resumeUi(uint16_t presentation){if(request_!=Request::UiRefresh)return false;summary_.presentation=presentation;summary_.uiObserved=true;request_=Request::None;finish();return true;}
 unsigned nextClocks(int previousWrite=-1)const{if(!depth_||request_!=Request::None)return 0;const auto&f=*frames_[depth_-1];return std::visit([&](const auto&t)->unsigned{using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,EditSceneTask>)return t.nextClocks(sceneCost(t,previousWrite));else if constexpr(std::is_same_v<T,EditAddressTask>)return t.nextClocks(addressCost(t,previousWrite));else if constexpr(std::is_same_v<T,EditDecisionTask>)return t.nextClocks(decisionCost(t,previousWrite));else return t.nextClocks(byteClock(0x17526,previousWrite));},f.task);}
 template<class R,class W>unsigned advanceBefore(unsigned available,R&&read,W&&write,int previousWrite=-1){const auto cost=nextClocks(previousWrite);if(!cost||cost>available)return 0;effect_={};auto&f=*frames_[depth_-1];auto&o=summary_.calls[f.node];
  auto byte=[&](uint32_t a,unsigned back=0){if(!dataSpan(a,1))throw std::logic_error("Unsupported evolving scene read");return uint8_t(read(a&0xffffff,cost-back));};
  auto wide=[&](uint32_t a){uint32_t value=0;for(unsigned n=0;n<4;++n)value=(value<<8)|byte(a+n,3*((3-n)/2));return value;};
  auto base=[&](uint32_t a,unsigned bytes){const auto value=wide(a);if(!dataSpan(value,bytes))throw std::logic_error("Unsupported evolving scene base");return value;};
  auto put=[&](uint32_t a,uint8_t v){if(!dataSpan(a,1))throw std::logic_error("Unsupported evolving scene write");write(a&0xffffff,v,cost);};
  std::visit([&](auto&t){using T=std::decay_t<decltype(t)>;
   if constexpr(std::is_same_v<T,EditSceneTask>){using S=typename T::Stage;const auto stage=t.stage();
    t.advanceBefore(cost,[&](S s)->uint32_t{switch(s){case S::ActivateReadBank:return o.facts.bank=byte(0x1679e);case S::ApplyReadEdit:case S::RestoreReadEdit:case S::BackupReadEdit:case S::CopyReadEdit:return o.facts.table=base(0x1748e,s==S::ApplyReadEdit||s==S::RestoreReadEdit?48:64);case S::ApplyReadPatch:case S::RestoreReadPatch:return o.facts.patch=base(0x167bc,256);case S::ApplyReadIndex:case S::RestoreReadIndex:return o.facts.lastParameter=byte(t.table()+t.index()*2,2);case S::ApplyReadValue:case S::RestoreReadEnabled:return o.facts.lastEnabled=byte(t.table()+t.index()*2+1,2);case S::ApplyReadOld:o.facts.parameterUsed=true;return o.facts.lastOld=byte(t.target());case S::RestoreReadPrevious:o.facts.previousObserved=true;return o.facts.previous=byte(0x167a0);case S::RestoreReadSelected:o.facts.selectedObserved=true;return o.facts.selected=byte(0x1679e);case S::RestoreReadOld:o.facts.parameterUsed=true;return o.facts.lastOld=byte(0x17495 + t.index());case S::BackupRead:return o.facts.lastByte=byte(t.table()+t.index(),2);case S::CopyRead:return o.facts.lastByte=byte(0x1734e + t.index(),2);default:throw std::logic_error("Unsupported scene read phase");}},[&](S s,uint32_t v){switch(s){case S::ActivatePublishPrevious:put(0x167a0,uint8_t(v));break;case S::ApplyPublishValue:case S::RestorePublishValue:put(t.target(),uint8_t(v));break;case S::ApplyPublishOld:put(0x17495 + t.index(),uint8_t(v));break;case S::RestorePublishSelected:case S::RestorePublishSelection:put(0x1679e,uint8_t(v));break;case S::RestorePublishPrevious:put(0x167a0,uint8_t(v));break;case S::BackupPublish:put(0x1734e + t.index(),uint8_t(v));break;case S::CopyPublish:put(t.table()+t.index(),uint8_t(v));break;default:throw std::logic_error("Unsupported scene write phase");}},[&](S){return sceneCost(t,previousWrite);});
    if(stage==S::RestoreRetainSelection)effect_.write=true;if(stage==S::RestoreReleaseSelection)effect_.read=true;
    if(t.awaitingChild()){effect_.write=true;using C=typename T::Child;if(t.child()==C::Load){o.facts.loaded=true;push(Kind::Load,f.input);}else if(t.child()==C::Apply){auto i=f.input;i.savePrevious=t.savePrevious();o.facts.applied=true;push(Kind::Apply,i);}else push(Kind::Notify,f.input);}
    else if(t.complete()){effect_.read=true;finish();}
   }else if constexpr(std::is_same_v<T,EditAddressTask>){using S=typename T::Stage;const auto stage=t.stage();
    t.advanceBefore(cost,[&](S s)->uint32_t{switch(s){case S::MapRead:return o.facts.selection=byte(0x17493);case S::LoadRead:return o.facts.lastByte=byte(t.page()+t.index(),2);case S::BankRead:return o.facts.bank=byte(0x1679e);default:throw std::logic_error("Unsupported scene address read");}},[&](S s,uint32_t v){switch(s){case S::MapPublish:put(0x17494,uint8_t(v));break;case S::LoadPublishEdit:for(unsigned n=0;n<4;++n)write(0x1748e + n,uint8_t(v>>(24-8*n)),cost-3*((3-n)/2));break;case S::LoadPublish:put(0x1738e + t.index(),uint8_t(v));break;default:throw std::logic_error("Unsupported scene address write");}},[&](S){return addressCost(t,previousWrite);});
    if(t.awaitingChild()){effect_.write=true;push(Kind::Bank,f.input);}else if(t.complete()){o.address=t;effect_.read=true;finish();}(void)stage;
   }else if constexpr(std::is_same_v<T,EditDecisionTask>){using S=typename T::Stage;const auto stage=t.stage();
    t.advanceBefore(cost,[&](S s)->uint32_t{switch(s){case S::KnobReadOld:return o.facts.oldKnob=byte(0x1679d);case S::KnobReadLock:return o.facts.lock=byte(0x16790);case S::KnobReadMode:return o.facts.knobMode=byte(0x1679f);case S::SelectReadMode:return o.facts.mode=byte(0x1679f);case S::SelectReadOldBank:return o.facts.oldBank=byte(0x1679e);default:throw std::logic_error("Unsupported scene decision read");}},[&](S s,uint32_t v){switch(s){case S::KnobPublishInput:put(0x1679d,uint8_t(v));break;case S::KnobPublishZeroBank:case S::SelectPublishBank:put(0x1679e,uint8_t(v));break;case S::KnobPublishZeroMode:case S::SelectPublishMode:put(0x1679f,uint8_t(v));break;case S::SelectClearRow:put(0x17492,uint8_t(v));break;case S::SelectClearField:put(0x17493,uint8_t(v));break;default:throw std::logic_error("Unsupported scene decision write");}},[&](S){return decisionCost(t,previousWrite);});
    if(stage==S::KnobDifference)o.facts.knobMagnitude=uint8_t(o.facts.oldKnob-uint8_t(f.input.event>>8));if(stage==S::KnobMagnitude)o.facts.knobMagnitude=uint8_t(0-o.facts.knobMagnitude);if(stage==S::KnobDifference||stage==S::KnobMagnitude)summary_.presentation=uint16_t((f.input.event&0xff00)|o.facts.knobMagnitude);o.facts.bank=t.bank();if(t.awaitingChild()){effect_.write=true;using C=typename T::Child;switch(t.child()){case C::RestoreScene:push(Kind::Restore,f.input);break;case C::Notify:push(Kind::Notify,f.input);break;case C::Map:push(Kind::Map,f.input);break;case C::ActivateScene:push(Kind::Activate,f.input);break;default:throw std::logic_error("Unsupported scene decision child");}}
    else if(t.handoff()){if(t.route()!=T::Route::Refresh)throw std::logic_error("Unsupported scene decision tail");o.facts.ui=true;request_=Request::UiRefresh;}
    else if(t.complete()){effect_.read=true;finish();}(void)stage;
   }else{const auto stage=t.stage();t.advanceBefore(cost,[&](StateBankDisplayTask::Read r)->uint32_t{if(r!=StateBankDisplayTask::Read::SelectedPart)throw std::logic_error("Unsupported scene notify read");o.facts.selectedObserved=true;return o.facts.selected=byte(0x16798);},[&](uint8_t v){put(0x17526,v);},byteClock(0x17526,previousWrite));if(t.awaitingTail()){o.facts.voice=true;request_=Request::VoiceRefresh;}else if(t.complete()){effect_.read=true;finish();}(void)stage;}
  },f.task);if(depth_)select();return cost;
 }
 static bool dataSpan(uint32_t raw,unsigned n){const auto a=raw&0xffffff;return StateStoreService::dataSpan(raw,n)||(n&&a>=0x800000&&a<0x900000&&n<=0x900000-a);}
 template<class Peek>static bool admitted(Kind k,const Input&,Peek&&peek){auto wide=[&](uint32_t a){uint32_t v=0;for(unsigned n=0;n<4;++n)v=(v<<8)|uint8_t(peek((a+n)&0xffffff));return v;};if(k==Kind::Apply||k==Kind::Backup||k==Kind::Copy){if(!dataSpan(wide(0x1748e),k==Kind::Apply?48:64))return false;}if(k==Kind::Apply||k==Kind::Restore||k==Kind::Activate||k==Kind::Knob||k==Kind::SelectBank){if(!dataSpan(wide(0x167bc),256))return false;}return true;}
private:
 using Task=std::variant<EditSceneTask,EditAddressTask,EditDecisionTask,StateBankDisplayTask>;
 struct Frame{template<class T>Frame(T t,Input i,unsigned n):task(std::move(t)),input(i),node(n){}Task task;Input input;unsigned node;};
 void push(Kind k,Input i){if(depth_==frames_.size()||summary_.count==summary_.calls.size())throw std::logic_error("Scene semantic capacity");const auto n=summary_.count++;auto&o=summary_.calls[n];o.kind=k;o.input=i;if(depth_){auto&parent=summary_.calls[frames_[depth_-1]->node];if(parent.childCount==parent.children.size())throw std::logic_error("Scene child capacity");parent.children[parent.childCount++]=n;}if(k<=Kind::Copy)frames_[depth_++].emplace(EditSceneTask(EditSceneTask::Kind(unsigned(k)),i.savePrevious),i,n);else if(k<=Kind::Bank)frames_[depth_++].emplace(EditAddressTask(k==Kind::Map?EditAddressTask::Kind::Map:k==Kind::Load?EditAddressTask::Kind::Load:EditAddressTask::Kind::Bank),i,n);else if(k==Kind::Notify)frames_[depth_++].emplace(StateBankDisplayTask(StateBankDisplayTask::Entry::Select),i,n);else frames_[depth_++].emplace(EditDecisionTask(k==Kind::Knob?EditDecisionTask::Kind::Knob:EditDecisionTask::Kind::Select,uint8_t(i.event>>8),uint8_t(i.event),i.selectedBank),i,n);select();}
 void finish(){const auto child=summary_.calls[frames_[depth_-1]->node];frames_[--depth_].reset();if(!depth_)return;std::visit([&](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,EditAddressTask>){if(!t.resumeAddress(child.address.page(),child.address.offset()))throw std::logic_error("Scene address child completion");}else if constexpr(std::is_same_v<T,EditSceneTask>){if(!t.resumeChild())throw std::logic_error("Scene child completion");}else if constexpr(std::is_same_v<T,EditDecisionTask>){if(!t.resumeChild())throw std::logic_error("Scene decision child completion");}},frames_[depth_-1]->task);select();}
 void select(){component_=std::visit([](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,EditSceneTask>)return Component::Scene;else if constexpr(std::is_same_v<T,EditAddressTask>)return Component::Address;else if constexpr(std::is_same_v<T,EditDecisionTask>)return Component::Decision;else return Component::Notify;},frames_[depth_-1]->task);components_|=1u<<unsigned(component_);}
 static unsigned byteClock(uint32_t raw,int previous=-1){const auto a=raw&0xffffff;return a<0x400000&&!(previous&1)&&a==(uint32_t(previous)|1u)?0u:3u;}
 static unsigned sceneCost(const EditSceneTask&t,int previous){using S=EditSceneTask::Stage;switch(t.stage()){case S::ApplyReadEdit:case S::ApplyReadPatch:case S::RestoreReadEdit:case S::RestoreReadPatch:case S::BackupReadEdit:case S::CopyReadEdit:return 6;case S::ActivatePublishPrevious:case S::RestorePublishPrevious:return byteClock(0x167a0,previous);case S::ApplyPublishValue:case S::RestorePublishValue:return byteClock(t.target(),previous);case S::ApplyPublishOld:return byteClock(0x17495 + t.index(),previous);case S::RestorePublishSelected:case S::RestorePublishSelection:return byteClock(0x1679e,previous);case S::BackupPublish:return byteClock(0x1734e + t.index(),previous);case S::CopyPublish:return byteClock(t.table()+t.index(),previous);default:return 3;}}
 static unsigned addressCost(const EditAddressTask&t,int previous){using S=EditAddressTask::Stage;switch(t.stage()){case S::MapPublish:return byteClock(0x17494,previous);case S::LoadPublishEdit:return 6;case S::LoadPublish:return byteClock(0x1738e + t.index(),previous);default:return 3;}}
 static unsigned decisionCost(const EditDecisionTask&t,int previous){using S=EditDecisionTask::Stage;switch(t.stage()){case S::KnobPublishInput:return byteClock(0x1679d,previous);case S::KnobPublishZeroBank:case S::SelectPublishBank:return byteClock(0x1679e,previous);case S::KnobPublishZeroMode:case S::SelectPublishMode:return byteClock(0x1679f,previous);case S::SelectClearRow:return byteClock(0x17492,previous);case S::SelectClearField:return byteClock(0x17493,previous);default:return 3;}}
 Kind kind_;Input input_;std::array<std::optional<Frame>,5>frames_{};unsigned depth_=0;Request request_=Request::None;Component component_=Component::Scene;uint32_t components_=0;Effect effect_{};Summary summary_{};
};
}
